import{teamPreviewVerified,onTeamPreviewChange}from './team-preview-access.js';
const tabs={schedule:'Расписание',students:'Ученики',homework:'Задания'};
const sample={schedule:'<h2>Ближайшее занятие</h2><p class="knowledge-eyebrow">ТАДЖВИД · ПРИМЕР</p><h3>Огласовки и короткие гласные</h3><p>Учебная группа · 3 ученика · 30 минут</p><button class="button" type="button" data-demo-lesson>Посмотреть занятие</button>',students:'<h2>Учебная группа</h2><p>Примерные ученики для знакомства с кабинетом.</p>'+['Первый ученик','Второй ученик','Третий ученик'].map((name,i)=>'<article class="team-demo-student"><span class="team-demo-avatar">'+(i+1)+'</span><span><strong>'+name+'</strong><small>Повторение огласовок</small></span><span class="team-demo-progress">'+[75,50,25][i]+'%</span></article>').join(''),homework:'<h2>Задание на повторение</h2><p>Прочитать примеры с фатхой, касрой и даммой. В настоящем кабинете здесь будут ответы учеников и комментарии преподавателя.</p><button class="button secondary" type="button" data-demo-feedback>Показать пример обратной связи</button><p class="team-demo-feedback" hidden>Хорошо! Повторите второй пример медленнее и обратите внимание на краткость гласного.</p>'};
let active=null;
export function stopTeamLearningDemo(){if(!active)return;active.off?.();active.root.remove();active=null;}
export function mountTeamLearningDemo(host,feature){
 if(!teamPreviewVerified()||!['teacher-preview','online-lessons'].includes(feature))return false;
 if(active?.host===host&&active.feature===feature&&active.root.isConnected)return true;
 stopTeamLearningDemo();const root=document.createElement('section');root.className='owner-learning-shell team-learning-demo';
 const teacher=feature==='teacher-preview';let tab='schedule';
 root.innerHTML='<a class="alphabet-back" href="#knowledge">← Знания</a><div class="page-head"><div><span class="knowledge-eyebrow">УЧЕБНЫЙ ПРИМЕР</span><h1 tabindex="-1">'+(teacher?'Кабинет преподавателя':'Онлайн-занятия')+'</h1><p>Познакомьтесь с возможностями на примерных данных.</p></div></div>'+(teacher?'<div class="team-demo-tabs" role="tablist" aria-label="Кабинет преподавателя">'+Object.entries(tabs).map(([id,label])=>'<button class="button secondary" type="button" role="tab" id="team-demo-tab-'+id+'" aria-controls="team-demo-panel" data-demo-tab="'+id+'">'+label+'</button>').join('')+'</div><section id="team-demo-panel" class="panel section" role="tabpanel"></section>':'<section class="team-demo-classroom"><div class="team-demo-video"><span class="team-demo-avatar">S</span><strong>Преподаватель SALAH</strong><small>Учебный экран занятия</small></div><div class="team-demo-material"><span class="knowledge-eyebrow">ПОВТОРЯЕМ ОГЛАСОВКИ</span><p lang="ar" dir="rtl">بَ بِ بُ</p><span>Фатха · Касра · Дамма</span></div><div class="team-demo-lesson-tools"><span>Микрофон</span><span>Видео</span><span>Показ материала</span></div><p>Здесь показано расположение видео и учебного материала. Подключение к настоящему занятию происходит по приглашению преподавателя.</p><a class="button secondary" href="#knowledge?view=teacher-preview">Посмотреть кабинет преподавателя</a></section>');
 const draw=()=>{if(!teacher)return;root.querySelector('#team-demo-panel').innerHTML=sample[tab];root.querySelector('#team-demo-panel').setAttribute('aria-labelledby','team-demo-tab-'+tab);for(const button of root.querySelectorAll('[data-demo-tab]')){button.setAttribute('aria-selected',String(button.dataset.demoTab===tab));button.tabIndex=button.dataset.demoTab===tab?0:-1;}};
 root.onclick=event=>{if(!teamPreviewVerified())return;const button=event.target.closest('button');if(button?.dataset.demoTab){tab=button.dataset.demoTab;draw();}else if(button?.hasAttribute('data-demo-lesson'))location.hash='knowledge?view=online-lessons';else if(button?.hasAttribute('data-demo-feedback')){const feedback=root.querySelector('.team-demo-feedback');feedback.hidden=!feedback.hidden;button.setAttribute('aria-expanded',String(!feedback.hidden));}};
 root.onkeydown=event=>{const button=event.target.closest('[data-demo-tab]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const ids=Object.keys(tabs),i=ids.indexOf(tab);tab=event.key==='Home'?ids[0]:event.key==='End'?ids.at(-1):ids[(i+(event.key==='ArrowRight'?1:ids.length-1))%ids.length];draw();root.querySelector('[data-demo-tab="'+tab+'"]').focus();};
 host.replaceChildren(root);draw();active={host,root,feature,off:onTeamPreviewChange(()=>{if(!teamPreviewVerified())stopTeamLearningDemo();})};return true;
}
